//! Device-generated "compact state" metadata tail.
//!
//! Most messages sent by the official app end with a tail like:
//!
//! ```text
//! DA 00 0E <u16 id>... 5A "statusByte" 5E "clockTimestamp" ... 5D "From Nanocore" ...
//! ```
//!
//! * `0x5A`, `0x5E`, `0x5D` are string markers of the form `0x50 | len`.
//! * The strings are generated by the **device firmware** (they are absent
//!   from both `libapp.so` and `liblivtra.so`), and the app echoes them back.
//!
//! Whether the device requires this tail on write commands is not yet known;
//! it is safest to reuse a tail captured from the official app.

/// Marker that begins the metadata tail (`statusByte` string marker).
pub const STATUS_MARKER: [u8; 11] = [
    0x5A, b's', b't', b'a', b't', b'u', b's', b'B', b'y', b't', b'e',
];

/// Header bytes that begin the device-generated state block.
pub const TAIL_HEADER: [u8; 3] = [0xDA, 0x00, 0x0E];

/// Find the byte offset where the metadata tail begins.
pub fn find_tail(payload: &[u8]) -> Option<usize> {
    if let Some(i) = payload.windows(3).position(|w| w == TAIL_HEADER) {
        return Some(i);
    }
    payload
        .windows(STATUS_MARKER.len())
        .position(|w| w == STATUS_MARKER)
        .map(|i| i.saturating_sub(1))
}

/// Return the "core" payload with any metadata tail removed.
pub fn core_payload(payload: &[u8]) -> &[u8] {
    match find_tail(payload) {
        Some(off) => &payload[..off],
        None => payload,
    }
}

/// Extract a raw tail (everything from the `DA 00 0E` block, if detectable).
pub fn extract_tail(payload: &[u8]) -> Option<&[u8]> {
    let start = payload.windows(3).position(|w| w == [0xDA, 0x00, 0x0E])?;
    Some(&payload[start..])
}
